def _decode(value: str) -> str:
    return base64.b85decode(value.encode("ascii")).decode("utf-8")


def _load_module(name: str, source: str) -> types.ModuleType:
    module = types.ModuleType(name)
    module.__file__ = __file__
    module.__package__ = ""
    sys.modules[name] = module
    exec(compile(source, __file__, "exec"), module.__dict__)
    return module


def _prepare_retarget_source() -> tuple[Path, Path]:
    runtime_dir = Path(tempfile.mkdtemp(prefix="wuji_l20_g20_teleop_"))
    source = runtime_dir / "wuji_l20_grasp_hw.py"
    from runtime.project_paths import human_urdf
    import os
    import re
    text = _decode(_RETARGET_B85)
    # Configuration substitutions only; the generated retarget is unchanged.
    text = text.replace('SN = "WG1KA06260622532"', f'SN = {os.environ.get("WUJI_GLOVE_SN", "WG1KA06260622532")!r}')
    text = re.sub(r'HUMAN_URDF = Path\(.*?\n\)',
                  lambda _: f'HUMAN_URDF = Path({str(human_urdf())!r})', text, count=1, flags=re.S) if not any(a in sys.argv for a in ("--help", "-h")) else text
    source.write_text(text, encoding="utf-8")
    atexit.register(shutil.rmtree, runtime_dir, True)
    return runtime_dir, source


def main() -> None:
    _runtime_dir, retarget_source = _prepare_retarget_source()
    v1 = _load_module("wuji_l20_onefile_teleop", _decode(_V1_B85))
    from runtime.project_paths import ROOT, portable_home
    v1.WS_SETUP = portable_home() / "linkerhand-telop-ros2/install/setup.bash"
    v1.BRIDGE_SRC = ROOT / "runtime/l20_bridge_template.py"
    v1.RETARGET_SRC = retarget_source

    # The G20 bridge consumes raw20.  These user-supplied q21 presets use
    # the first 20 fields for that protocol; the final q21 field is not a
    # motor channel.  The three stages reuse the existing pinch event names:
    # index = ball (ring+pinky), middle = box ready (three fingers),
    # ring = box grasp (three fingers, fully closed).
    staged_q21 = {
        "index": [255, 253, 253, 2, 10, 254, 192, 147, 118, 86, 245, 0, 0, 0, 0, 255, 253, 241, 107, 106, 106],
        "middle": [45, 254, 254, 21, 25, 136, 252, 253, 127, 91, 82, 0, 0, 0, 0, 255, 128, 124, 107, 106, 106],
        "ring": [46, 158, 163, 22, 26, 135, 253, 254, 127, 91, 82, 0, 0, 0, 0, 255, 129, 125, 96, 99, 99],
    }
    if any(len(anchor) != 21 for anchor in staged_q21.values()):
        raise ValueError("L20 staged grasp anchors must contain 21 values")
    v1.GUI_PINCH_ANCHORS_RAW20 = {
        name: values[:20] for name, values in staged_q21.items()
    }
    v1.GUI_PINCH_CHANNELS = {
        "index": [3, 8, 18, 4, 9, 19],
        "middle": [0, 5, 10, 15, 1, 6, 16, 2, 7, 17, 3, 8, 18],
        "ring": [0, 5, 10, 15, 1, 6, 16, 2, 7, 17, 3, 8, 18],
    }
    v1.GUI_PINCH_ANCHOR_ENABLED = True
    _load_module("wuji_l20_onefile_teleop_v2", _decode(_V2_B85))

    # Keep V8's command-line defaults without retaining a wrapper file.
    if "--control-hz" not in sys.argv[1:]:
        sys.argv.extend(("--control-hz", "120"))
    print(
        "[L20/G20 120Hz] staged dual-object grasp anchors",
        flush=True,
    )
    v6_source = _decode(_V6_B85).replace("Path.home()", f"Path({str(portable_home())!r})")
    # Generated bridge children inherit the local vendor package roots.
    import os
    os.environ["PYTHONPATH"] = os.pathsep.join((str(ROOT / "vendor"),
        str(ROOT / "vendor/linkerhand_retarget"), os.environ.get("PYTHONPATH", "")))
    # Only WS default changes in generated bridge code; the V6 patch templates
    # still see their original source text.
    v6_source = v6_source.replace("        bridge_py = patch_bridge_v6(tmpdir)",
        "        bridge_py = patch_bridge_v6(tmpdir)\n"
        "        bridge_py.write_text(bridge_py.read_text().replace('Path.home()', "
        f"\"Path({str(portable_home())!r})\"))")
    exec(compile(v6_source, __file__, "exec"), globals())


if __name__ == "__main__":
    main()
